INSERT INTO `whatsapp_plantilla` VALUES (1,'boleta','Boleta emitida','Hola {nombre} ?\n\nTe enviamos tu *Boleta Electr├│nica*\nN┬░ {comprobante}\nTotal: *{total}*\n{tipo_doc}: {documento}\n\n\"? Muchas gracias por visitarnos hoy en Cevicher├¡a Yapez. Esperamos que hayas disfrutado de nuestro sabor marino. ??\n\nTe adjunto tu boleta electr├│nica por el consumo realizado. ┬íQue tengas un excelente d├¡a y esperamos verte pronto! ?\"\n\nDescarga tu comprobante:\n\n{link_pdf}',1,'cobro',1,'2026-05-10 12:24:44'),(2,'factura','Factura emitida','Hola {nombre} ?\n\nTe enviamos tu *Factura Electr├│nica*\nN┬░ {comprobante}\nTotal: *{total}*\nRUC: {documento}\n\nGracias por confiar en *{empresa}* ?\n\nDescarga tu comprobante:\n{link_pdf}',1,'cobro',1,'2026-05-10 12:24:44'),(3,'cumple','Cumplea├▒os del cliente','? ┬íFeliz cumplea├▒os {nombre}! ?\n\nEn *{empresa}* queremos celebrar contigo.\nTe invitamos a disfrutar de un *15% de descuento* en tu pr├│ximo pedido como regalo de cumplea├▒os.\n\nV├ílido durante todo el d├¡a.\n┬íEsperamos verte pronto! ?\n\n? {telefono_empresa}',0,'cumple',1,'2026-05-10 12:24:44'),(4,'navidad','Navidad','? ┬íFeliz Navidad {nombre}! Ô£¿\n\nEn *{empresa}* te deseamos paz, amor y mucha alegr├¡a junto a tu familia en estas fiestas.\n\nGracias por ser parte de nuestra familia este a├▒o ?\n\nQue el 2027 te traiga muchas bendiciones.\n\nÔÇö El equipo de {empresa}',0,'festivo',1,'2026-05-10 12:24:44'),(5,'ano_nuevo','A├▒o Nuevo','? ┬íFeliz A├▒o Nuevo {nombre}! ?\n\nQue este nuevo a├▒o te traiga salud, prosperidad y muchos momentos felices.\n\nGracias por confiar en *{empresa}* durante el a├▒o que termina.\n\n┬íTe esperamos en el 2027 con nuevos sabores y promociones! ?\n\nÔÇö Tu cevicher├¡a de confianza',0,'festivo',1,'2026-05-10 12:24:44'),(6,'madres','D├¡a de la Madre','? ┬íFeliz D├¡a de la Madre {nombre}! ÔØñÔÖÑÔÖÑ\n\n? En Cevicher├¡a Yapez sabemos que no hay amor m├ís puro que el tuyo. Gracias por existir y por permitirnos ser parte de tus momentos especiales. ÔØñ\n\nHoy el homenajeado es tu paladar. ┬íTe esperamos para celebrar como te mereces con el mejor sabor marino! ???\n\nReserva tu mesa: Ô£ï {telefono_empresa}\n\n┬íTe esperamos para celebrar a las mam├ís como se merecen!',0,'festivo',1,'2026-05-10 12:24:44'),(7,'padres','D├¡a del Padre','?ÔÇì? ┬íFeliz D├¡a del Padre {nombre}! ?\n\nCelebra a pap├í con un buen ceviche en *{empresa}*.\nTenemos *promociones especiales* para esta fecha.\n\nReserva: ? {telefono_empresa}\n\n┬íLo esperamos para hacer de su d├¡a algo inolvidable!',0,'festivo',1,'2026-05-10 12:24:44'),(8,'patrias','Fiestas Patrias','?? ┬íFelices Fiestas Patrias {nombre}! ?\n\nCelebra el cumplea├▒os del Per├║ con la mejor comida criolla en *{empresa}*.\n\n? Combos especiales por Fiestas Patrias\n? Ambiente peruano\n\n? {telefono_empresa}\n\n┬íViva el Per├║!',0,'festivo',1,'2026-05-10 12:24:44'),(9,'promocion','Promoci├│n Especial','? ┬íHola {nombre}! ?\n\nTenemos una *promoci├│n especial* solo para nuestros clientes:\n\n[Aqu├¡ describe tu promoci├│n]\n\n? {telefono_empresa}\n? Vis├¡tanos en *{empresa}*\n\n┬íNo te lo pierdas! ÔÅ░',0,'promocion',1,'2026-05-10 12:24:44'),(10,'gracias','Gracias por tu visita','┬íGracias por visitarnos {nombre}! ?\n\nEn *{empresa}* siempre es un gusto atenderte.\n\nTu opini├│n es muy importante para nosotros.\n┬┐C├│mo estuvo tu experiencia hoy?\n\n┬íTe esperamos pronto! ?',0,'generico',1,'2026-05-10 12:24:44');
